import json
from itertools import permutations

def solve_puzzle():
    # Puzzle parameters
    houses = [1, 2, 3, 4]  # house numbers left to right
    names = ["Peter", "Arnold", "Alice", "Eric"]
    colors = ["yellow", "green", "red", "white"]

    solutions = []

    for name_assign in permutations(names):
        # Constraint 2: Peter is in the first house (index 0)
        if name_assign[0] != "Peter":
            continue

        # Constraint 4: Arnold is directly left of Eric
        pos_arnold = name_assign.index("Arnold")
        pos_eric = name_assign.index("Eric")
        if pos_arnold + 1 != pos_eric:
            continue

        for color_assign in permutations(colors):
            # Constraint 1: The person whose favorite color is green is in the third house (index 2)
            if color_assign[2] != "green":
                continue

            # Constraint 5: Eric is the person who loves yellow
            if color_assign[pos_eric] != "yellow":
                continue

            # Constraint 3: One house between red and yellow
            if abs(color_assign.index("red") - color_assign.index("yellow")) != 2:
                continue

            # All constraints satisfied
            solutions.append((name_assign, color_assign))

    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    # If multiple, choose the first deterministically
    name_solution, color_solution = solutions[0]

    # Build the output JSON structure
    output = {
        "solution": {
            "header": ["House", "Name", "Color"],
            "rows": [
                [str(houses[i]), name_solution[i], color_solution[i]] for i in range(len(houses))
            ],
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
